  prep: ["Vocal stems + Beat instrumental", "ตัวอย่างร้องจม / S เด่น / ระดับไม่นิ่ง", "Vocal chain ตัวอย่างสำหรับสาธิต"],
  exercise: "ให้นักเรียนมิกซ์ร้องเข้ากับบีททั้งเพลงเวอร์ชันแรก",
